    fn lock_history(&self) -> MutexGuard<'_, AgentReplayHistory> {
        match self.history.lock() {
            Ok(history) => history,
            Err(poison) => {
                let mut history = poison.into_inner();
                history.recompute_encoded_bytes();
                history
            }
        }
    }

    pub(crate) fn emit(&self, event: AgentTurnEvent) {
