        &self,
    ) -> (
        Vec<AgentEventEnvelope>,
        broadcast::Receiver<AgentEventEnvelope>,
    ) {
        let history = self.lock_history();
        let rx = self.tx.subscribe();
        let replay = history.iter().cloned().collect();
        (replay, rx)
